<?php

namespace App\Actions\Mcp;

use App\Actions\Pages\SavePage;
use App\Models\Page;
use Illuminate\Validation\ValidationException;

/**
 * Create an inactive static page for the MCP create_page_draft tool (M3-S1,
 * S3, S5): SavePage with a null page (no existing page is loaded). Forced:
 * inactive, needs review, not system, default template. The slug is always
 * generated by SavePage and never a system slug or an existing one.
 */
class CreateMcpPageDraft
{
    public function __construct(private SavePage $save) {}

    /**
     * @param  array{title: array<string, string|null>, body?: array<string, string|null>, meta_title?: array<string, string|null>, meta_description?: array<string, string|null>}  $data
     *
     * @throws ValidationException
     */
    public function handle(array $data): Page
    {
        return $this->save->handle(null, [
            'title' => $data['title'],
            'body' => $data['body'] ?? [],
            'meta_title' => $data['meta_title'] ?? [],
            'meta_description' => $data['meta_description'] ?? [],
            'template' => 'default',
            'sort' => null,
            'is_active' => false,
            'needs_review' => true,
        ]);
    }
}
